import sys,json
sys.path.insert(0,'submission')
from crosscheck import CrossCheck
S={'trials':2,'epsilon':0,'seed':7,'cutoff':[0,1],'bias':0,'tau':0,'gamma':[1,1],'cache_slots':0}
def topo(rev):
 nodes=[{'id':0,'name':'A','external_capacity':100},{'id':1,'name':'B','external_capacity':100}]
 links=[{'source':0,'target':1,'capacity':100}] if not rev else [{'source':1,'target':0,'capacity':100}]
 return {'nodes':nodes,'links':links,'external_nodes':['A','B']}
counters={'low_A_egress_to_B':{'perturbed':10},'low_B_ingress_from_A':{'perturbed':10},'low_B_egress_to_A':{'perturbed':3},'low_A_ingress_from_B':{'perturbed':3},'low_A_origination':{'perturbed':10},'low_A_termination':{'perturbed':3},'low_B_origination':{'perturbed':3},'low_B_termination':{'perturbed':10}}
routes={'A':{'B':[{'path':['A','B'],'weight':1000}]},'B':{'A':[{'path':['B','A'],'weight':1000}]}}
ev=[{'op':'patch','demands':[[0,1,10],[1,0,3]],'counters':counters},{'op':'routes','label':'x','paths':routes},{'op':'repair','id':'r'}]
a=CrossCheck(topo(False)).replay(ev,S);b=CrossCheck(topo(True)).replay(ev,S)
print(a[0]==b[0],a[1]==b[1],a[2]==b[2])
